845	### Task 3.4 ∥ W4: dictionary in-loop limit, `getOrPut`, statistics after the decision
846	
847	- Files: `zig-parquet/src/core/column_writer.zig` (`writeColumnChunkDictOptionalWithPathArray`,
848	  `writeColumnChunkByteArrayDictOptionalWithPathArray`)
849	- Depends on: Gate 2 (∥ with 3.1-3.3 and 3.6; sequential before 3.5)
850	- Change, typed function. Remove the "Compute statistics" block at the top and the post-loop
851	  "Check dictionary size limit" block. Rewrite the build loop:
852	
853	```zig
854	    var idx: usize = 0;
855	    for (values) |v| {
856	        if (v != .null_value) {
857	            const gop = unique_map.getOrPut(v.value) catch return error.OutOfMemory;
858	            if (!gop.found_existing) {
859	                gop.value_ptr.* = try safe.castTo(u32, dict_values.items.len);
860	                dict_values.append(allocator, v.value) catch return error.OutOfMemory;
861	                // The dictionary only grows, so its first excess is the same decision
862	                // the old post-loop check made: fall back now instead of hashing on.
863	                if (dictionary_size_limit) |limit| {
864	                    if (dict_values.items.len * @sizeOf(T) > limit) {
865	                        return writeColumnChunkOptionalWithPathArray(T, allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
866	                    }
867	                }
868	            }
869	            indices[idx] = gop.value_ptr.*;
870	            idx += 1;
871	            // ...existing cardinality-threshold block, minus its two `stats` lines...
872	        }
873	    }
874	
875	    const dict_size = dict_values.items.len;
876	
877	    // Statistics are only needed once the dictionary is kept (fallbacks compute their own).
878	    var stats_builder = statistics.StatisticsBuilder(T){};
879	    stats_builder.updateOptional(values);
880	    const stats = stats_builder.build(allocator) catch return error.OutOfMemory;
881	    errdefer if (stats) |s| freeStatistics(allocator, s);
882	```
883	
884	  Byte-array function: same shape with `std.StringHashMap` `getOrPut(val)`, keeping the
885	  `val.len > maxInt(i32)` check **before** `getOrPut`, `dict_bytes += 4 + val.len` on insert and
886	  `if (dict_bytes > limit)` fallback. Statistics (`ByteArrayStatisticsBuilder`) move below the loop
887	  in the same way.
888	- Test: tests pass on both versions (`writer_basic_test`, `roundtrip_test` dictionary and fallback cases).
889	- Acceptance: str_unique write ≥ 3x baseline (≥ 10M rows/s); mixed5 write ≥ 2x baseline;
890	  str_dict not slower; `file_MB` unchanged.
891	
892	### Task 3.5 W5: dictionary data pages built in one buffer
893	
894	- Files: `zig-parquet/src/core/column_writer.zig` (page loops of the same two functions)
895	- Depends on: 3.2, 3.4
896	- Change: in each data-page loop, replace the `data_page_uncompressed = if (is_optional) blk: {...} else blk: {...}`
897	  expression and its `defer allocator.free(data_page_uncompressed)` with:
898	
899	```zig
900	        // [def levels (optional only)][bit width][indices], built in one buffer.
901	        var page_buf: std.ArrayList(u8) = .empty;
902	        defer page_buf.deinit(allocator);
903	        if (is_optional) try rle_encoder.appendDefLevelsWithLength(T, &page_buf, allocator, page_values);
904	        page_buf.append(allocator, bit_width) catch return error.OutOfMemory;
905	        page_buf.appendSlice(allocator, rle_data) catch return error.OutOfMemory;
906	        const data_page_uncompressed = page_buf.items;
907	```
908	
909	  (In the byte-array function `T` is `[]const u8`.)
910	- Acceptance: str_dict write +15% or more; mixed5 write +10% or more; `file_MB` unchanged.
911	
912	### Task 3.6 ∥ W6: byte-array statistics without a copy per new extreme
913	
914	- Files: `zig-parquet/src/core/statistics.zig` (`ByteArrayStatisticsBuilder.update`, `.updateOptional`)
915	- Depends on: Gate 2
916	- Change (same pattern for `update`):
917	
918	```zig
919	    pub fn updateOptional(self: *Self, values: []const Optional([]const u8)) !void {
920	        var lo: ?[]const u8 = null;
921	        var hi: ?[]const u8 = null;
922	        for (values) |v| switch (v) {
923	            .null_value => self.null_count += 1,
924	            .value => |val| {
925	                if (lo == null or std.mem.order(u8, val, lo.?) == .lt) lo = val;
926	                if (hi == null or std.mem.order(u8, val, hi.?) == .gt) hi = val;
927	            },
928	        };
929	        // At most two owned copies per call instead of one per new extreme.
930	        if (lo) |l| try self.updateValue(l);
931	        if (hi) |h| try self.updateValue(h);
932	    }
933	```
934	
935	- Test: tests pass on both versions (statistics tests, page-index tests that read min/max).
936	- Acceptance: no regression; str_unique write not slower (gain is small and expected to be within noise).
